import React from 'react'
import '../../styles/Section2Style.css'
import Chili from '../../assets/images/chili.avif'

const Section2 = () => {
  return (
    <section className="slogan">
      {/* slogan */}
      <div className="slogan-content">
        <p>Authentic and delicious flavor made with love and tradition.</p>
        
      </div>
      {/* veggies */}
      <div className="veggies">
        <img src={Chili} className="veggie chili" alt="" />
        <img src={Alecri} className="veggie chili2" alt="" />
      </div>

    </section>
  )
}

export default Section2
